// UNVERIFIED: written without a Mac; never compiled or run. See README.md.
#include "meld_store.h"

#import <Foundation/Foundation.h>
#import "meld_store-Swift.h" // generated by Xcode for MeldStoreKit.swift

MeldStore *MeldStore::instance = nullptr;

static NSString *to_ns(const String &s) {
	return [NSString stringWithUTF8String:s.utf8().get_data()];
}

static String to_gd(NSString *s) {
	return String::utf8([s UTF8String]);
}

MeldStore *MeldStore::get_singleton() {
	return instance;
}

void MeldStore::_bind_methods() {
	ClassDB::bind_method(D_METHOD("products"), &MeldStore::products);
	ClassDB::bind_method(D_METHOD("purchase", "id"), &MeldStore::purchase);
	ClassDB::bind_method(D_METHOD("restore"), &MeldStore::restore);
	ADD_SIGNAL(MethodInfo("purchased", PropertyInfo(Variant::STRING, "id")));
	ADD_SIGNAL(MethodInfo("restored", PropertyInfo(Variant::ARRAY, "ids")));
	ADD_SIGNAL(MethodInfo("failed", PropertyInfo(Variant::STRING, "id"), PropertyInfo(Variant::STRING, "reason")));
}

Array MeldStore::products() const {
	return product_list;
}

void MeldStore::_set_products(const Array &list) {
	product_list = list;
}

void MeldStore::purchase(String id) {
	[[MeldStoreKit shared] purchase:to_ns(id)];
}

void MeldStore::restore() {
	[[MeldStoreKit shared] restore];
}

MeldStore::MeldStore() {
	ERR_FAIL_COND(instance != nullptr);
	instance = this;
	MeldStoreKit *kit = [MeldStoreKit shared];
	kit.onPurchased = ^(NSString *pid) {
		if (MeldStore::instance) {
			MeldStore::instance->emit_signal("purchased", to_gd(pid));
		}
	};
	kit.onFailed = ^(NSString *pid, NSString *reason) {
		if (MeldStore::instance) {
			MeldStore::instance->emit_signal("failed", to_gd(pid), to_gd(reason));
		}
	};
	kit.onRestored = ^(NSArray<NSString *> *ids) {
		if (MeldStore::instance) {
			Array out;
			for (NSString *i in ids) {
				out.push_back(to_gd(i));
			}
			MeldStore::instance->emit_signal("restored", out);
		}
	};
	kit.onProducts = ^(NSArray<NSDictionary<NSString *, NSString *> *> *list) {
		if (MeldStore::instance) {
			Array out;
			for (NSDictionary<NSString *, NSString *> *p in list) {
				Dictionary d;
				d["id"] = to_gd(p[@"id"]);
				d["price"] = to_gd(p[@"price"]);
				out.push_back(d);
			}
			MeldStore::instance->_set_products(out);
		}
	};
	// the one product: keep in step with Entitlement.FULL_ID
	[kit start:@[ @"com.meldlings.full" ]];
}

MeldStore::~MeldStore() {
	if (instance == this) {
		instance = nullptr;
	}
}
